{
  "decision": "BLOCK",
  "findings": [
    {
      "severity": "high",
      "file": "cloud_pilot/multilingual/activation_review.py",
      "detail": "Topic deduplication examines repository articles and a historical corpus index, but does not check the target site's current URLs or content. The supplied site observations expressly say they were not a website-wide audit. A distinct verdict therefore does not establish that the proposed buyer intent is distinct from existing live pages.",
      "required_fix": "Add a traceable current target-site URL and content check to the topic gate. Bind its evidence to the independent dedup receipt and hold when live-site coverage is insufficient. Test a live-site duplicate absent from the repository corpus."
    },
    {
      "severity": "high",
      "file": "cloud_pilot/live/stages.py",
      "detail": "check_writing accepts an internal link when its path appears in history['entries']; that structural history includes research and other repository records, not just verified live pages on the target site. An English draft can therefore pass with a link that does not exist on the live site.",
      "required_fix": "Validate each proposed internal link against a current, target-site-specific live URL record, or require an empty link list when verification is unavailable. Add tests for historical draft-only paths and previously live but unavailable paths."
    }
  ],
  "human_reviewed": false,
  "publish_approved": false
}
